    '目が覚めたら、支度の時間が半分になっていた。\n\nまつげを片方だけ諦めて、店に走った。\n\n「走ってきたの、顔でわかるよ」\n店長はそれ以上、何も言わなかった。何も言われないのが、一番痛い。',
    'ヘアセットの店が押していた。\n\n「30分でお願いします」と言ったのに、椅子を立てたのは50分後だった。\n\n店に着くと、店長が仁王立ちで待っていた。\n\n「遅い」\n短く、それだけ。',
