  // 流しを続けすぎたときの店長【叩き台】
  nagashiScoldScene: '閉店後、着替えて出ようとしたところで店長に呼び止められた。\n\n「──最近ちょっと適当すぎない？　お客さんにもバレてるよ」\n\n言い返す言葉が、なかった。\n\n「早く上がるのは別にいい。けどな、卓に座ってる時間まで"流し"てたら、指名なんか一生つかないよ」\n\nロッカーの扉が、いつもより重かった。',

