    '「……なあ。そんなもんでいいの、君は」\n言われて、初めて気づく。もう一段、上が通っていたのかもしれない。',
    '「もうちょっと、自分の値段を知りなさい」\n笑いながら言われた。……笑いながら言うことじゃない。',
    '「ずいぶん安く見られたもんだな、俺も」\n──違う。安く見ていたのは、たぶん、自分のほうだ。',
    '「遠慮すんなよ。……遠慮って、要するに"この人はここまで"って値踏みだからね」\n静かに刺さった。',
    '「君さ。もう一声、言えたでしょ」\n見透かされていた。ねだる前から、負けていた。',
    '「その値段で満足されると、こっちの立つ瀬がないんだけどな」\n冗談めかしていたが、目は本気だった。',
