    '「キミさあ、この仕事、その顔で大変じゃない？」\n悪気のない声だった。悪気がないのが、一番深く刺さるのだと、この客は知らない。\nおしぼりを置く手が、少しだけ震えた。',
    '「チェンジって言ったら、怒る？　……はは、冗談だって」\n冗談。冗談か。\n笑顔を作る。頬の筋肉だけで作る笑顔の作り方が、うまくなっていく。',
