  // アフター【叩き台】
  afterScenes: {
    fun: '深夜のラーメン屋。店の照明の下で見る顔は、卓で見るより少し普通で、少しだけ若かった。\n\n仕事の話も、店の話もしなかった。くだらない話で2回笑った。\n\n「──今度さ、ちゃんと指名で行くわ。本指名ってやつ」\n伝票を取りながら、彼はさらっと言った。\n\n……眠い。眠いけど、足取りは軽い。\nいいお客さんも、いるもんだな。',
    bore: '深夜のラーメン屋。話は仕事の自慢の無限ループだった。3周目からは相槌が自動になった。\n\n「で、俺がその案件をさあ」\nはい。すごいですね。はい。\n\n語りが長くて、麺が伸びた。解散は2時半。\n……この時間、まるごと寝たかった。',
    declineSoft: '「そっか。ごめんごめん、遅くまで引き止めて。おやすみ」\n意外なほど、あっさりしていた。……大人だ。\n少しだけ申し訳なくなったが、布団の勝ちだった。',
    declineRule: '「ルールなら仕方ないな。ま、また店で」\n店のせいにするのは、いつだって少し便利で、少しずるい。\n背中に小さく手を振って、終電に走った。',
    declineAngry: '「……あっそ。ノリわりいな、あんた」\n捨て台詞が、夜道に転がった。\n\n断り方を、間違えた。あしらっていいのは卓の上だけだ。\n……終電の窓に映る顔が、ちょっと疲れていた。',
  },

  // 店長のお叱り【叩き台】
  scoldScene: '閉店後、レジ締めの途中で店長に手招きされた。\n\n「──さっきの卓。何をどう聞いたら、ああなるの」\n\n言い訳は、3つ思いついて、3つとも飲み込んだ。\n「お客さんは、葉っぱ一枚で帰る船だからね。……明日、フリーの卓は他の子に回すから。頭冷やして」\n\n説教は長く、終電は行ってしまった。',

  // 謝罪の夜【叩き台】
