  // 売掛飛びの朝【叩き台】
  tobiScene: '開店前、店長に呼ばれた。嫌な予感は、だいたい当たる。\n\n「例の、財布忘れたって客。……飛んだわ。電話も繋がらないし、会社ももう辞めてるらしい」\n\n「売掛はあんたの判断で通したんだよね。立て替えはあんたの負担。……それがこの商売のルールなの」\n\n「ちゃんと払います」って、言ったのに。あの固い乾杯の音、本物だと思ったのに。\n……信用は財産だ。でも、転がし方を間違えると借金になる。',

