    'まつエクのリペア': '朝、鏡を見たら右目だけまつ毛が3本足りなかった。\n夜の照明は、こういうのを見逃してくれない。\n\nリペア40分。目を閉じている間だけ、少し眠れた。\nこれは出費じゃなくて、目元の武装。……ということにする。',
    'コスメの補充': '下地、ファンデ、リップ、まつ毛のり。減るときは、ぜんぶ一緒に減る。\n\nドラッグストアのカゴが、あっという間に埋まっていく。\n「夜のライトに勝てる肌」は、毎月これだけの銃弾を消費して維持されている。\n……戦争なのだ、あの照明の下は。',
    '美容院（カラー＋トリートメント）': '「だいぶ傷んでますね〜」\n毎晩の巻き髪とスプレーの報いが、美容師さんの指先で発覚する。\n\nカラーを整えて、トリートメントを足して、お会計。\n夜の店の照明は、髪の艶で女を値踏みしてくる。負けられない。',
