      desc: 'ファンクラブ限定トークイベント、抽選結果──【ご当選おめでとうございます】。\n\n……は？　当たった？　あの倍率で？\n参加費と物販と交通費で25,000円。日程は仕事を休まなくても行ける。問題は、金だけ。金だけが、問題。',
      cost: 25000, buyLabel: '行く。当選は義務',     buyMental: 45,
