  // =====================================================================
  // 母イベント【叩き台】
  //   元日に打ち明けた（隠した）その先。部屋にいる朝、母から電話が来る。
  //   中盤＝反対、終盤＝和解。day指定で朝イチに発火（oshiEventsと同じ形式）
  // =====================================================================
  motherEvents: [
    { day: 55, title: '母からの電話、今度は違う声', bg: 'scene_room',
      scene: '部屋で支度をしていたら、スマホが鳴った。母だった。\n\n「ニュースでね、夜遅くまでやってる店のトラブル、やってたのよ。……あんたのバイト、大丈夫なの？」\n\n「大丈夫だよ」\n\n「大丈夫って、それしか言わないじゃない。……あんた、ほんとは何の店で働いてるの」\n\n初めて聞く、母の強い声だった。',
      choice: [
        { label: '「まだ、やめられない。理由があるの」と伝える',
          scene: '「理由？　理由って何よ」\n\n答えられなかった。推しのことも、ツアーのことも、うまく言葉にならなかった。\n「……ごめん、また電話する」\n\n通話が切れたあとの静けさが、いつもより重かった。',
          effects: { mental: -8 } },
        { label: '黙って、電話を切る',
          scene: '「もしもし？　……ねえ」\n\n何も言えないまま、通話を終わらせた。\n\nスマホの画面が暗くなる。実家の番号が、しばらく光ったままだった。',
          effects: { mental: -12 } },
      ],
      next: '出勤の支度を、続けた' },
    // 日付だけで撃っていたら、勝った人は24人中0人が読めなかった（クリアは Day53〜81）。
    // 「Day90」か「目標の7割まで貯めた朝」の早いほうで撃つ。負けた人にも必ず届く
    { day: 90, orMoney: 700000, minDay: 60, after: 55, title: '母から、短いメッセージ', bg: 'scene_room',
      scene: '部屋で朝の支度をしていたら、母からLINEが届いた。\n\n「この前は言いすぎた。\nあんたが理由を言わなかったのは、言えない理由があるからだって、あとで思った。\n……お金、足りてるの？　それだけ教えなさい」\n\n最後の一言だけ、いつもの母だった。\n\n既読をつけて、少しだけ、泣いた。理由は、自分でもよくわからなかった。',
      effects: { mental: 30 },
      next: '……よし。今夜も行こう' },
  ],

  // =====================================================================
  // VIP雑用ミッション【叩き台】
